package org.simpleweather.app;
import android.app.*;
import android.widget.*;
import android.text.*;
import java.time.*;
import java.util.function.Consumer;

/** Direct digit fields only, never the platform clock-face picker. */
final class NumericInputs {
    static EditText number(MainActivity a,LinearLayout row,String label,int value,int digits){LinearLayout col=a.column();col.addView(a.text(label,13,a.MUTED,false));EditText f=new EditText(a);f.setInputType(InputType.TYPE_CLASS_NUMBER);f.setSingleLine(true);f.setSelectAllOnFocus(true);f.setText(String.valueOf(value));f.setTextSize(18);f.setFilters(new InputFilter[]{new InputFilter.LengthFilter(digits)});f.setContentDescription(label);col.addView(f,a.lp(-1,52));if(row.getChildCount()>0)a.gapHorizontal(row,8);row.addView(col,new LinearLayout.LayoutParams(0,-2,1));return f;}
    static void time(MainActivity a,LocalTime initial,Consumer<LocalTime> done){LinearLayout row=a.row();row.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));EditText h=number(a,row,UiText.get("numeric_inputs_001"),initial.getHour(),2),m=number(a,row,UiText.get("numeric_inputs_002"),initial.getMinute(),2);AlertDialog d=new ToolDialog(a).setTitle(UiText.get("numeric_inputs_003")).setView(row).setPositiveButton(UiText.get("numeric_inputs_004"),null).setNegativeButton(UiText.get("action_cancel"),null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{LocalTime t=LocalTime.of(Integer.parseInt(h.getText().toString()),Integer.parseInt(m.getText().toString()));done.accept(t);d.dismiss();}catch(Exception e){a.toast(UiText.get("numeric_inputs_005"));}}));d.show();}
    static void dateTime(MainActivity a,ZonedDateTime initial,Consumer<Instant> done){LinearLayout c=a.column();c.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));LinearLayout date=a.row();EditText y=number(a,date,UiText.get("numeric_inputs_008"),initial.getYear(),4),mo=number(a,date,UiText.get("numeric_inputs_009"),initial.getMonthValue(),2),day=number(a,date,UiText.get("numeric_inputs_010"),initial.getDayOfMonth(),2);c.addView(date);LinearLayout time=a.row();EditText h=number(a,time,UiText.get("numeric_inputs_011"),initial.getHour(),2),mi=number(a,time,UiText.get("numeric_inputs_012"),initial.getMinute(),2);c.addView(time);a.gap(c,12);c.addView(a.text(UiText.get("numeric_inputs_006")+EarthquakeOptions.offset(initial.getZone(),initial.toInstant().toEpochMilli())+UiText.get("numeric_inputs_007"),13,a.MUTED,false));AlertDialog d=new ToolDialog(a).setTitle(UiText.get("numeric_inputs_013")).setView(c).setPositiveButton(UiText.get("numeric_inputs_004"),null).setNegativeButton(UiText.get("action_cancel"),null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{int year=Integer.parseInt(y.getText().toString());if(year<1900||year>2100)throw new Exception();LocalDateTime local=LocalDateTime.of(year,Integer.parseInt(mo.getText().toString()),Integer.parseInt(day.getText().toString()),Integer.parseInt(h.getText().toString()),Integer.parseInt(mi.getText().toString()));if(initial.getZone().getRules().getValidOffsets(local).isEmpty()){a.toast(UiText.get("numeric_inputs_014"));return;}done.accept(local.atZone(initial.getZone()).toInstant());d.dismiss();}catch(Exception e){a.toast(UiText.get("numeric_inputs_015"));}}));d.show();}
}
